mapper.select:
select
c1.C_Name as cName,
c1.C_Abbreviation as cAbbName,
mn.*
from Fund_Plan_Dtl_Check mn
left join SYS_Company c1 on mn.Fpdc_Cid=c1.C_Id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Fpd_Id=#{params.fpdId}
    
    
        and INSTR(mn.Fpdc_Uname,#{params.fpdcUname})
    
    
        and INSTR(mn.Fpdc_Node_Name,#{params.fpdcNodeName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Fpdc_Time desc
